/* implementor side: operations table + instance pointer */
typedef struct RendererOps { void (*circle)(void *self, double r); } RendererOps;
typedef struct { const RendererOps *ops; void *self; } Renderer;

/* abstraction side: a shape owns a Renderer and forwards the primitive */
typedef struct { Renderer renderer; double radius; } CircleShape;

static void circle_shape_draw(const CircleShape *s) {
    s->renderer.ops->circle(s->renderer.self, s->radius);
}

/* renderer.h: the implementor interface */
#define RENDERER_TYPE (renderer_get_type ())
G_DECLARE_INTERFACE (Renderer, renderer, MY, RENDERER, GObject)

struct _RendererInterface {
    GTypeInterface parent_iface;
    void (*circle) (Renderer *self, double r);
};

void renderer_circle (Renderer *self, double r) {
    RENDERER_GET_IFACE (self)->circle (self, r);   /* forwards to the implementor */
}

